import{_ as u,a0 as p,w as a,s as r,ao as l,I as o,x as t,a1 as i,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"Linux 的逆袭 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 的逆袭 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 的逆袭 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 的逆袭 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160803 The revenge of Linux","title":"Linux 的逆袭","tag":"201609","desc":""},"relativePath":"201609/20160803 The revenge of Linux.md","filePath":"[post].md"}'),x={name:"201609/20160803 The revenge of Linux.md"};function L(d,e,f,m,T,g){const n=p("Link");return a(),r("div",null,[e[13]||(e[13]=l('<h1 id="linux-的逆袭" tabindex="-1">Linux 的逆袭 <a class="header-anchor" href="#linux-的逆袭" aria-label="Permalink to “Linux 的逆袭”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/penguin%20swimming.jpg?itok=mfhEdRdM" alt=""></p><p>Linux 系统在早期的时候被人们嘲笑，它什么也干不了。而现在，Linux 无处不在！</p><p>我当时还是个在巴西学习计算机工程的大三学生，并同时在一个全球审计和顾问公司兼职系统管理员。公司决定用 Oracle 数据库开发一些企业资源计划（ERP）软件。因此，我得以在 Digital UNIX OS (DEC Alpha) 进行训练，这个训练颠覆了我的三观。</p><p>UNIX 系统非常的强大，而且给予了我们对机器上包括存储系统、网络、应用和其他一切的绝对控制权。</p><p>我开始在 ksh 和 Bash 里编写大量的脚本让系统进行自动备份、文件传输、提取转换加载（ETL）操作、自动化 DBA 日常工作，还为各种不同的项目创建了许多服务。此外，调整数据库和操作系统的工作让我更好的理解了如何让服务器以最佳方式运行。在那时，我在自己的个人电脑上使用的是 Windows 95 系统，而我非常想要在我的个人电脑里放进一个 Digital UNIX，或者哪怕是 Solaris 或 HP-UX 也行，但是那些 UNIX 系统都得在特定的硬件才能上运行。我阅读了所有的系统文档，还找过其它的书籍以求获得更多的信息，也在我们的开发环境里对这些疯狂的想法进行了实验。</p><p>后来在大学里，我从我的同事那听说了 Linux。我那时非常激动的从还在用拨号方式连接的因特网上下载了它。在我的正宗的个人电脑里装上 UNIX 这类系统的这个想法真是太酷了！</p><p>Linux 不同于 UNIX 系统，它设计用来在各种常见个人电脑硬件上运行，在起初，让它开始工作确实有点困难，Linux 针对的用户群只有系统管理员和极客们。我为了让它能运行，甚至用 C 语言修改了驱动软件。我之前使用 UNIX 的经历让我在编译 Linux 内核，排错这些过程中非常的顺手。由于它不同于那些只适合特定硬件配置的封闭系统，所以让 Linux 跟各种意料之外的硬件配置一起工作真的是件非常具有挑战性的事。</p><p>我曾见过 Linux 在数据中心获得一席之地。一些具有冒险精神的系统管理员使用它来帮他们完成每天监视和管理基础设施的工作，随后，Linux 作为 DNS 和 DHCP 服务器、打印管理和文件服务器等赢得了更多的使用。企业曾对 Linux 有着很多顾虑（恐惧，不确定性，怀疑(FUD:fear, uncertainty and doubt)）和诟病：谁是它的拥有者？由谁来支持它？有适用于它的应用吗？</p><p>但现在看来，Linux 在各个地方进行着逆袭！从开发者的个人电脑到大企业的服务器；我们能在智能手机、智能手表以及像树莓派这样的物联网（IoT）设备里找到它。甚至 Mac OS X 有些命令跟我们所熟悉的命令一样。微软在制造它自己的发行版，在 Azure 上运行，然后…… Windows 10 要装备 Bash。</p><p>有趣的是 IT 市场会不断地创造并迅速的用新技术替代，但是我们所掌握的 Digital UNIX、HP-UX 和 Solaris 这些旧系统的知识还依然有效并跟 Linux 息息相关，不论是为了工作还是玩。现在我们能完全的掌控我们的系统，并使它发挥最大的效用。此外，Linux 有个充满热情的社区。</p><p>我真的建议想在计算机方面发展的年轻人学习 Linux，不论你处于 IT 界里的哪个分支。如果你深入了解了一个普通的家用个人电脑是如何工作的，你就可以以基本相同的方式来面对任何机器。你可以通过 Linux 学习最基本的计算机知识，并通过它建立能在 IT 界任何地方都有用的能力！</p><hr>',13)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),i(n,{href:"https://opensource.com/life/16/8/revenge-linux"},{default:s(()=>[...e[0]||(e[0]=[t("https://opensource.com/life/16/8/revenge-linux",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),i(n,{href:"https://opensource.com/users/danielscarvalho"},{default:s(()=>[...e[2]||(e[2]=[t("Daniel Carvalho",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),i(n,{href:"https://github.com/H-mudcup"},{default:s(()=>[...e[3]||(e[3]=[t("H-mudcup",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),i(n,{href:"https://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const N=u(x,[["render",L]]);export{I as __pageData,N as default};
